def backtrack(path):
    if is_complete(path):
        res.append(path[:]); return
    for choice in options(path):
        path.append(choice)
        backtrack(path)
        path.pop()

for choice in options:
    if not is_valid(path, choice):
        continue
    make_move(choice)
    backtrack(path)
    undo_move(choice)

def solve():
    if complete(): return True
    for choice in options:
        if valid(choice):
            apply(choice)
            if solve(): return True
            undo(choice)
